126	function CopyButton({ text }: { text: string }) {
127	  const [copied, setCopied] = useState(false);
128	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
129	
130	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
131	
132	  const handleCopy = async () => {
133	    if (timerRef.current) clearTimeout(timerRef.current);
134	    try {
135	      await navigator.clipboard.writeText(text);
136	    } catch {
137	      const textarea = document.createElement("textarea");
138	      textarea.value = text;
139	      document.body.appendChild(textarea);
140	      textarea.select();
141	      document.execCommand("copy");
142	      document.body.removeChild(textarea);
143	    }
144	    setCopied(true);
145	    timerRef.current = setTimeout(() => setCopied(false), 2000);
146	  };
147	
148	  return (
149	    <TooltipProvider delayDuration={200}>
150	      <Tooltip>
151	        <TooltipTrigger asChild>
152	          <button
153	            onClick={handleCopy}
154	            className={cn(
155	              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
156	              copied
157	                ? "bg-green-50 text-green-600 border border-green-200"
158	                : "bg-card/80 text-slate-500 border border-border/50 hover:bg-muted/40 hover:text-foreground"
159	            )}
160	          >
161	            {copied ? (
162	              <><Check className="h-3 w-3" />Copied</>
163	            ) : (
164	              <><Copy className="h-3 w-3" />Copy</>
165	            )}
166	          </button>
167	        </TooltipTrigger>
168	        <TooltipContent side="top">
169	          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
170	        </TooltipContent>
171	      </Tooltip>
172	    </TooltipProvider>
173	  );
174	}
