// ── Enhanced Executive Summary Page ──────────────────────────────

function buildEnhancedExecutiveSummary(
  doc: jsPDF,
  scan: Scan,
  pillarResults: PillarResult[],
  accent: [number, number, number],
): void {
  doc.addPage();
  enhancedPageHeader(doc, accent, "ConvertScan CRO Audit Report", "Executive Summary");

  let y = 18;
  y = sectionHeading(doc, "Executive Summary", y);

  // Overall score row
  const score = scan.overall_score ?? 0;
  const interpretation = enhancedScoreInterpretation(score);
  doc.setFillColor(...BRAND.slate50);
  doc.roundedRect(MARGIN, y, CONTENT_W, 28, 2, 2, "F");
  scorePill(doc, score, MARGIN + 20, y + 14, 10);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(13);
  doc.setTextColor(...BRAND.slate900);
  doc.text(`${Math.round(score)}/100 — ${interpretation}`, MARGIN + 36, y + 10);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.setTextColor(...BRAND.slate500);
  doc.text(
    `${scan.url} · ${scan.page_type} page`,
    MARGIN + 36,
    y + 19,
    { maxWidth: CONTENT_W - 40 },
  );
  y += 35;

  // Top 3 Quick Wins (effort=quick, severity critical/warning)
  y = sectionHeading(doc, "Top 3 Quick Wins", y);
  const allFindings = pillarResults.flatMap((pr) => pr.findings);
  const quickWins = allFindings
    .filter((f) => f.effort === "quick" && (f.severity === "critical" || f.severity === "warning"))
    .sort((a, b) => {
      const order: Record<string, number> = { critical: 0, warning: 1 };
      return (order[a.severity] ?? 2) - (order[b.severity] ?? 2);
    })
    .slice(0, 3);

  if (quickWins.length === 0) {
    doc.setFont("helvetica", "italic");
    doc.setFontSize(8.5);
    doc.setTextColor(...BRAND.slate500);
    doc.text("No high-impact quick wins identified.", MARGIN, y + 5);
    y += 14;
  } else {
    quickWins.forEach((f, i) => {
      if (y > 200) { doc.addPage(); y = MARGIN + 15; }
      const sevRgb = severityRgb(f.severity);
      doc.setFillColor(...BRAND.slate50);
      doc.roundedRect(MARGIN, y, CONTENT_W, 22, 2, 2, "F");
      doc.setFillColor(...BRAND.green);
      doc.circle(MARGIN + 7, y + 11, 5, "F");
      doc.setTextColor(...BRAND.white);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(7.5);
      doc.text(`${i + 1}`, MARGIN + 7, y + 11.5, { align: "center", baseline: "middle" });
      doc.setFont("helvetica", "bold");
      doc.setFontSize(9);
      doc.setTextColor(...BRAND.slate900);
      doc.text(f.title, MARGIN + 15, y + 8);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(7.5);
      doc.setTextColor(...sevRgb);
      doc.text(getSeverityLabel(f.severity).toUpperCase(), MARGIN + 15, y + 16);
      if (f.estimated_lift) {
        doc.setTextColor(...BRAND.violet);
        doc.text(`Est. lift: ${f.estimated_lift}`, PAGE_W - MARGIN - 4, y + 8, { align: "right" });
      }
      y += 26;
    });
  }

  // Top 3 Critical Issues
  y = sectionHeading(doc, "Top 3 Critical Issues", y);
  const criticals = allFindings
    .filter((f) => f.severity === "critical")
    .slice(0, 3);

  if (criticals.length === 0) {
    doc.setFont("helvetica", "italic");
    doc.setFontSize(8.5);
    doc.setTextColor(...BRAND.slate500);
    doc.text("No critical issues found — great work!", MARGIN, y + 5);
    y += 14;
  } else {
    criticals.forEach((f, i) => {
      if (y > 220) { doc.addPage(); y = MARGIN + 15; }
      doc.setFillColor(...BRAND.slate50);
      doc.roundedRect(MARGIN, y, CONTENT_W, 22, 2, 2, "F");
      doc.setFillColor(...BRAND.red);
      doc.circle(MARGIN + 7, y + 11, 5, "F");
      doc.setTextColor(...BRAND.white);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(7.5);
      doc.text(`${i + 1}`, MARGIN + 7, y + 11.5, { align: "center", baseline: "middle" });
      doc.setFont("helvetica", "bold");
      doc.setFontSize(9);
      doc.setTextColor(...BRAND.slate900);
      doc.text(f.title, MARGIN + 15, y + 8);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(7.5);
      doc.setTextColor(...BRAND.slate500);
      const recPreview = f.recommendation.length > 100
        ? f.recommendation.slice(0, 97) + "…"
        : f.recommendation;
      doc.text(recPreview, MARGIN + 15, y + 16, { maxWidth: CONTENT_W - 20 });
      y += 26;
    });
  }

  // Findings count by severity
  if (y > 240) { doc.addPage(); y = MARGIN + 15; }
  const sevCounts: Record<string, number> = { critical: 0, warning: 0, info: 0, passed: 0 };
  for (const f of allFindings) sevCounts[f.severity] = (sevCounts[f.severity] ?? 0) + 1;
  const countRows = Object.entries(sevCounts)
    .filter(([, count]) => count > 0)
    .map(([sev, count]) => [
      getSeverityLabel(sev as "critical" | "warning" | "info" | "passed"),
      count.toString(),
    ]);

  autoTable(doc, {
    startY: y + 6,
    head: [["Severity", "Count"]],
    body: countRows,
    theme: "striped",
    styles: { font: "helvetica", fontSize: 8.5, cellPadding: 3 },
    headStyles: { fillColor: accent, textColor: BRAND.white, fontStyle: "bold" },
    columnStyles: {
      0: { cellWidth: 60 },
      1: { cellWidth: 30, halign: "center", fontStyle: "bold" },
    },
    alternateRowStyles: { fillColor: BRAND.slate50 },
    margin: { left: MARGIN, right: MARGIN },
  });
}

// ── Enhanced Pillar Breakdown Page ────────────────────────────────

function buildEnhancedPillarBreakdown(
  doc: jsPDF,
  pillarResults: PillarResult[],
  accent: [number, number, number],
): void {
  doc.addPage();
  enhancedPageHeader(doc, accent, "ConvertScan CRO Audit Report", "Pillar Breakdown");

  let y = 18;
  y = sectionHeading(doc, "Pillar Breakdown", y);

  // Score bar visualization per pillar
  pillarResults.forEach((pr) => {
    if (y > 248) { doc.addPage(); y = MARGIN + 15; }
    const cfg = CRO_PILLARS.find((c) => c.key === pr.pillar);
    const label = cfg?.label ?? pr.pillar;
    const rgb = scoreRgb(pr.score);
    const benchmark = getIndustryBenchmark(pr.pillar);

    doc.setFont("helvetica", "bold");
    doc.setFontSize(8.5);
    doc.setTextColor(...BRAND.slate900);
    doc.text(label, MARGIN, y + 4);

    const scoreStr = `${Math.round(pr.score)}/100`;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8.5);
    doc.setTextColor(...rgb);
    doc.text(scoreStr, PAGE_W - MARGIN, y + 4, { align: "right" });

    const barY = y + 7;
    const barW = CONTENT_W;
    doc.setFillColor(...BRAND.slate200);
    doc.roundedRect(MARGIN, barY, barW, 4, 1.5, 1.5, "F");
    const filledW = (pr.score / 100) * barW;
    doc.setFillColor(...rgb);
    doc.roundedRect(MARGIN, barY, filledW, 4, 1.5, 1.5, "F");
    // Benchmark marker
    const markerX = MARGIN + (benchmark / 100) * barW;
    doc.setFillColor(...BRAND.slate700);
    doc.rect(markerX - 0.4, barY - 1, 0.8, 6, "F");

    y += 16;
  });

  // Summary table
  y += 4;
  if (y > 200) { doc.addPage(); y = MARGIN + 15; }
  const tableRows = pillarResults.map((pr) => {
    const cfg = CRO_PILLARS.find((c) => c.key === pr.pillar);
    const benchmark = getIndustryBenchmark(pr.pillar);
    const diff = Math.round(pr.score) - benchmark;
    const status = enhancedScoreInterpretation(pr.score);
    return [
      cfg?.label ?? pr.pillar,
      `${Math.round(pr.score)}/100`,
      `${benchmark}/100`,
      status,
      diff >= 0 ? `+${diff}` : `${diff}`,
    ];
  });

  autoTable(doc, {
    startY: y,
    head: [["Pillar", "Score", "Industry Avg", "Status", "vs Avg"]],
    body: tableRows,
    theme: "grid",
    styles: { font: "helvetica", fontSize: 8, cellPadding: 3.5 },
    headStyles: { fillColor: accent, textColor: BRAND.white, fontStyle: "bold", fontSize: 8 },
    columnStyles: {
      0: { cellWidth: 50 },
      1: { cellWidth: 24, halign: "center" },
      2: { cellWidth: 26, halign: "center" },
      3: { cellWidth: 32 },
      4: { cellWidth: 22, halign: "center" },
    },
    didParseCell: (data) => {
      if (data.section === "body" && data.column.index === 1) {
        data.cell.styles.textColor = scoreRgb(pillarResults[data.row.index]?.score ?? 0);
        data.cell.styles.fontStyle = "bold";
      }
      if (data.section === "body" && data.column.index === 4) {
        const pr = pillarResults[data.row.index];
        if (pr) {
          const diff = pr.score - getIndustryBenchmark(pr.pillar);
          data.cell.styles.textColor = diff >= 0 ? BRAND.green : BRAND.red;
          data.cell.styles.fontStyle = "bold";
        }
      }
    },
    alternateRowStyles: { fillColor: BRAND.slate50 },
    margin: { left: MARGIN, right: MARGIN },
  });
}

// ── Enhanced Detailed Findings Pages ─────────────────────────────

function buildEnhancedDetailedFindings(
  doc: jsPDF,
  pillarResults: PillarResult[],
  accent: [number, number, number],
): void {
  const sorted = [...pillarResults].sort((a, b) => a.score - b.score);

  sorted.forEach((pr) => {
    const actionableFindings = pr.findings.filter((f) => f.severity !== "passed");
    if (actionableFindings.length === 0) return;

    doc.addPage();
    const rgb = scoreRgb(pr.score);
    enhancedPageHeader(doc, rgb, "ConvertScan · Detailed Findings", `${CRO_PILLARS.find((c) => c.key === pr.pillar)?.label ?? pr.pillar}`);

    let y = 18;
    const pillarLabel = CRO_PILLARS.find((c) => c.key === pr.pillar)?.label ?? pr.pillar;
    y = sectionHeading(doc, `${pillarLabel} — Score: ${Math.round(pr.score)}/100`, y);

    // Sort findings: critical first
    const sortedFindings = [...actionableFindings].sort((a, b) => {
      const order: Record<string, number> = { critical: 0, warning: 1, info: 2 };
      return (order[a.severity] ?? 3) - (order[b.severity] ?? 3);
    });

    sortedFindings.forEach((finding) => {
      const neededH = estimateFindingHeight(finding);
      if (y + neededH > 272) {
        doc.addPage();
        enhancedPageHeader(doc, rgb, "ConvertScan · Detailed Findings", `${pillarLabel} (continued)`);
        y = 18;
      }
      y = renderFinding(doc, finding, y);
      y += 5;
    });
  });
}

// ── Enhanced Copy Rewrites Page ───────────────────────────────────

function buildEnhancedCopyRewritesPage(
  doc: jsPDF,
  copyRewrites: CopyRewrite[],
  accent: [number, number, number],
): void {
  doc.addPage();
  enhancedPageHeader(doc, accent, "ConvertScan CRO Audit Report", "AI Copy Rewrites");

  let y = 18;
  y = sectionHeading(doc, "AI Copy Rewrites", y);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(...BRAND.slate500);
  doc.text(
    "AI-generated copy alternatives optimized for conversion. Test these against your current copy.",
    MARGIN,
    y,
    { maxWidth: CONTENT_W },
  );
  y += 10;

  const tableRows = copyRewrites.map((cr) => [
    cr.element_type.replace(/_/g, " "),
    cr.original.length > 80 ? cr.original.slice(0, 77) + "…" : cr.original,
    cr.suggested.length > 80 ? cr.suggested.slice(0, 77) + "…" : cr.suggested,
    cr.reasoning.length > 80 ? cr.reasoning.slice(0, 77) + "…" : cr.reasoning,
  ]);

  autoTable(doc, {
    startY: y,
    head: [["Element", "Original", "Suggested", "Reasoning"]],
    body: tableRows,
    theme: "striped",
    styles: { font: "helvetica", fontSize: 7.5, cellPadding: 3 },
    headStyles: { fillColor: accent, textColor: BRAND.white, fontStyle: "bold", fontSize: 8 },
    columnStyles: {
      0: { cellWidth: 26 },
      1: { cellWidth: 48 },
      2: { cellWidth: 48 },
      3: { cellWidth: 48 },
    },
    alternateRowStyles: { fillColor: BRAND.slate50 },
    margin: { left: MARGIN, right: MARGIN },
  });
}

// ── Enhanced Score History Page ───────────────────────────────────

function buildEnhancedScoreHistoryPage(
  doc: jsPDF,
  scoreHistory: Array<{ date: string; score: number }>,
  accent: [number, number, number],
): void {
  doc.addPage();
  enhancedPageHeader(doc, accent, "ConvertScan CRO Audit Report", "Score History");

  let y = 18;
  y = sectionHeading(doc, "Score History", y);

  const first = scoreHistory[0];
  const last = scoreHistory[scoreHistory.length - 1];
  const delta = last.score - first.score;
  const deltaLabel = delta >= 0 ? `+${delta}` : `${delta}`;
  const deltaRgb = delta >= 0 ? BRAND.green : BRAND.red;

  // Trend summary block
  doc.setFillColor(...BRAND.slate50);
  doc.roundedRect(MARGIN, y, CONTENT_W, 24, 2, 2, "F");
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(...BRAND.slate500);
  doc.text(`First scan: ${Math.round(first.score)}/100 on ${new Date(first.date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`, MARGIN + 6, y + 9);
  doc.text(`Latest scan: ${Math.round(last.score)}/100 on ${new Date(last.date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`, MARGIN + 6, y + 18);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(12);
  doc.setTextColor(...deltaRgb);
  doc.text(`${deltaLabel} pts`, PAGE_W - MARGIN - 6, y + 15, { align: "right" });
  y += 32;

  const tableRows = scoreHistory.map((entry) => [
    new Date(entry.date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }),
    `${Math.round(entry.score)}/100`,
    enhancedScoreInterpretation(entry.score),
  ]);

  autoTable(doc, {
    startY: y,
    head: [["Date", "Score", "Status"]],
    body: tableRows,
    theme: "striped",
    styles: { font: "helvetica", fontSize: 9, cellPadding: 3.5 },
    headStyles: { fillColor: accent, textColor: BRAND.white, fontStyle: "bold" },
    columnStyles: {
      0: { cellWidth: 60 },
      1: { cellWidth: 30, halign: "center" },
      2: { cellWidth: 40 },
    },
    didParseCell: (data) => {
      if (data.section === "body" && data.column.index === 1) {
        const row = scoreHistory[data.row.index];
        if (row) {
          data.cell.styles.textColor = scoreRgb(row.score);
          data.cell.styles.fontStyle = "bold";
        }
      }
    },
    alternateRowStyles: { fillColor: BRAND.slate50 },
    margin: { left: MARGIN, right: MARGIN },
  });
}

// ── Enhanced Footer ───────────────────────────────────────────────

function addEnhancedFooter(
  doc: jsPDF,
  pageNum: number,
  totalPages: number,
  dateStr: string,
  reportTitle: string,
): void {
  const y = PAGE_H - 10;
  doc.setFontSize(7.5);
  doc.setTextColor(...BRAND.slate500);
  doc.setFont("helvetica", "normal");
  doc.text(`Generated by ${reportTitle} — convertscan.com`, MARGIN, y);
  doc.text(`Page ${pageNum} of ${totalPages}`, PAGE_W / 2, y, { align: "center" });
  doc.text(dateStr, PAGE_W - MARGIN, y, { align: "right" });
  doc.setDrawColor(...BRAND.slate200);
  doc.setLineWidth(0.3);
  doc.line(MARGIN, y - 3, PAGE_W - MARGIN, y - 3);
}

// ── Main Enhanced Export ──────────────────────────────────────────

export async function generateEnhancedPDF(options: EnhancedPDFOptions): Promise<void> {
  const { scan, pillarResults, copyRewrites, scoreHistory, branding } = options;

  const doc = new jsPDF({ unit: "mm", format: "a4", orientation: "portrait" });

  const scanDate = scan.completed_at ?? scan.created_at;
  const dateStr = new Date(scanDate).toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  });

  const reportTitle = branding?.companyName ?? "ConvertScan";
  const accent: [number, number, number] = branding?.accentColor
    ? hexToRgb(branding.accentColor)
    : BRAND.indigo;

  // Page 1: Cover
  buildEnhancedCover(doc, scan, dateStr, accent, reportTitle);

  // Page 2: Executive Summary
  buildEnhancedExecutiveSummary(doc, scan, pillarResults, accent);

  // Page 3: Pillar Breakdown
  buildEnhancedPillarBreakdown(doc, pillarResults, accent);

  // Page 4+: Detailed Findings (per pillar)
  buildEnhancedDetailedFindings(doc, pillarResults, accent);

  // Copy Rewrites page (if provided and non-empty)
  if (copyRewrites && copyRewrites.length > 0) {
    buildEnhancedCopyRewritesPage(doc, copyRewrites, accent);
  }

  // Score History page (if provided and has 2+ entries)
  if (scoreHistory && scoreHistory.length >= 2) {
    buildEnhancedScoreHistoryPage(doc, scoreHistory, accent);
  }

  // Footer on every page
  const totalPages = doc.getNumberOfPages();
  for (let p = 1; p <= totalPages; p++) {
    doc.setPage(p);
    addEnhancedFooter(doc, p, totalPages, dateStr, reportTitle);
  }

  // Save
  const safeDomain = scan.url
    .replace(/^https?:\/\//, "")
    .replace(/[^a-zA-Z0-9-]/g, "-")
    .slice(0, 40);
  doc.save(`convertscan-audit-${safeDomain}.pdf`);
}

