/**
 * PDFOptionsDialog.tsx
 *
 * Lets the user choose between a Basic PDF (existing generateAuditPDF)
 * and an Enhanced PDF (generateEnhancedPDF — Pro+ only).
 * Enhanced options include optional company name, accent color, and
 * toggles for copy rewrites and score history sections.
 */

import { useState } from "react";
import { generateAuditPDF, generateEnhancedPDF } from "@/lib/pdf-generator";
import { useCopyRewrites } from "@/hooks/use-copy-rewrites";
import { useScanHistory } from "@/hooks/use-scan-history";
import { useAuth } from "@/contexts/AuthContext";
import { isProPlus } from "@/types";
import type { Scan, PillarResult } from "@/types";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Separator } from "@/components/ui/separator";
import { Download, RefreshCw, Lock, Sparkles, FileText } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

// ── Preset accent colors ──────────────────────────────────────────

const PRESET_COLORS: Array<{ label: string; hex: string }> = [
  { label: "Indigo", hex: "#6366f1" },
  { label: "Violet", hex: "#7c3aed" },
  { label: "Blue", hex: "#2563eb" },
  { label: "Emerald", hex: "#059669" },
  { label: "Rose", hex: "#e11d48" },
  { label: "Amber", hex: "#d97706" },
];

// ── Props ─────────────────────────────────────────────────────────

interface PDFOptionsDialogProps {
  scan: Scan;
  pillarResults: PillarResult[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

// ── Component ─────────────────────────────────────────────────────

export function PDFOptionsDialog({
  scan,
  pillarResults,
  open,
  onOpenChange,
}: PDFOptionsDialogProps) {
  const { profile } = useAuth();
  const isProUser = profile ? isProPlus(profile.plan) : false;

  // Form state
  const [pdfType, setPdfType] = useState<"basic" | "enhanced">("basic");
  const [companyName, setCompanyName] = useState(profile?.company_name ?? "");
  const [accentColor, setAccentColor] = useState("#6366f1");
  const [customHex, setCustomHex] = useState("");
  const [includeRewrites, setIncludeRewrites] = useState(true);
  const [includeHistory, setIncludeHistory] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);

  // url_hash for scan history: same derivation as AuditReport.tsx
  const urlHash = scan.url.toLowerCase().trim();

  const { data: copyRewrites = [] } = useCopyRewrites(scan.id);
  const { data: historyEntries = [] } = useScanHistory(urlHash);
  const scoreHistory = historyEntries.map((e) => ({
    date: e.scanned_at,
    score: e.score,
  }));

  const hasRewrites = copyRewrites.length > 0;
  const hasHistory = scoreHistory.length >= 2;

  // Resolve effective accent color (custom hex takes precedence if valid)
  const effectiveAccent =
    customHex.match(/^#[0-9a-fA-F]{6}$/) ? customHex : accentColor;

  const handleDownload = async () => {
    if (pillarResults.length === 0) {
      toast.error("Report data not ready. Please wait and try again.");
      return;
    }

    setIsGenerating(true);
    try {
      if (pdfType === "basic") {
        await new Promise<void>((resolve) => {
          setTimeout(() => {
            generateAuditPDF(scan, pillarResults, {
              full_name: profile?.full_name ?? "User",
              company_name: profile?.company_name ?? undefined,
            });
            resolve();
          }, 0);
        });
        toast.success("Basic PDF downloaded.");
      } else {
        await generateEnhancedPDF({
          scan,
          pillarResults,
          copyRewrites: includeRewrites && hasRewrites ? copyRewrites : undefined,
          scoreHistory: includeHistory && hasHistory ? scoreHistory : undefined,
          branding: {
            companyName: companyName.trim() || undefined,
            accentColor: effectiveAccent,
          },
        });
        toast.success("Enhanced PDF downloaded.");
      }
      onOpenChange(false);
    } catch (err) {
      console.error("PDF generation error:", err);
      toast.error("Failed to generate PDF. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Download className="h-4.5 w-4.5 text-primary" />
            Download PDF Report
          </DialogTitle>
          <DialogDescription>
            Choose the format that best fits your needs.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 py-2">
          {/* ── PDF Type Selection ─────────────────────────────── */}
          <RadioGroup
            value={pdfType}
            onValueChange={(v) => setPdfType(v as "basic" | "enhanced")}
            className="space-y-3"
          >
            {/* Basic */}
            <label
              htmlFor="pdf-basic"
              className={cn(
                "flex cursor-pointer items-start gap-3 rounded-lg border p-3.5 transition-colors",
                pdfType === "basic"
                  ? "border-primary/60 bg-primary/5"
                  : "border-border/60 hover:bg-muted/40"
              )}
            >
              <RadioGroupItem value="basic" id="pdf-basic" className="mt-0.5 shrink-0" />
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <FileText className="h-4 w-4 text-muted-foreground" />
                  <span className="text-sm font-semibold text-foreground">Basic PDF</span>
                </div>
                <p className="mt-0.5 text-xs text-muted-foreground">
                  Cover page, executive summary, pillar breakdown, and quick wins.
                  Available on all plans.
                </p>
              </div>
            </label>

            {/* Enhanced */}
            <label
              htmlFor="pdf-enhanced"
              className={cn(
                "flex cursor-pointer items-start gap-3 rounded-lg border p-3.5 transition-colors",
                pdfType === "enhanced"
                  ? "border-primary/60 bg-primary/5"
                  : "border-border/60 hover:bg-muted/40",
                !isProUser && "opacity-70"
              )}
            >
              <RadioGroupItem
                value="enhanced"
                id="pdf-enhanced"
                className="mt-0.5 shrink-0"
                disabled={!isProUser}
              />
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <Sparkles className="h-4 w-4 text-violet-500" />
                  <span className="text-sm font-semibold text-foreground">
                    Enhanced PDF
                  </span>
                  {!isProUser && (
                    <span className="inline-flex items-center gap-1 rounded-full border border-amber-200 bg-amber-50 px-2 py-0.5 text-2xs font-semibold text-amber-700">
                      <Lock className="h-2.5 w-2.5" />
                      Pro+
                    </span>
                  )}
                </div>
                <p className="mt-0.5 text-xs text-muted-foreground">
                  Multi-page branded report with custom colors, detailed findings,
                  AI copy rewrites, and score history.
                </p>
              </div>
            </label>
          </RadioGroup>

          {/* ── Enhanced Options (Pro+ only) ───────────────────── */}
          {pdfType === "enhanced" && (
            <>
              <Separator />

              {isProUser ? (
                <div className="space-y-4">
                  {/* Company name */}
                  <div className="space-y-1.5">
                    <Label htmlFor="company-name" className="text-sm font-medium">
                      Company Name
                      <span className="ml-1 text-xs text-muted-foreground">(optional)</span>
                    </Label>
                    <Input
                      id="company-name"
                      value={companyName}
                      onChange={(e) => setCompanyName(e.target.value)}
                      placeholder="Your company name"
                      className="h-9 text-sm"
                    />
                    <p className="text-xs text-muted-foreground">
                      Replaces "ConvertScan" in the report header and footer.
                    </p>
                  </div>

                  {/* Accent color */}
                  <div className="space-y-1.5">
                    <Label className="text-sm font-medium">Accent Color</Label>
                    <div className="flex flex-wrap gap-2">
                      {PRESET_COLORS.map((color) => (
                        <button
                          key={color.hex}
                          type="button"
                          title={color.label}
                          onClick={() => {
                            setAccentColor(color.hex);
                            setCustomHex("");
                          }}
                          className={cn(
                            "h-7 w-7 rounded-full border-2 transition-all",
                            effectiveAccent === color.hex
                              ? "border-foreground scale-110 shadow-md"
                              : "border-transparent hover:scale-105"
                          )}
                          style={{ backgroundColor: color.hex }}
                        />
                      ))}
                    </div>
                    <div className="flex items-center gap-2">
                      <Input
                        value={customHex}
                        onChange={(e) => setCustomHex(e.target.value)}
                        placeholder="#1a2b3c"
                        maxLength={7}
                        className="h-8 w-28 font-mono text-xs"
                      />
                      <span className="text-xs text-muted-foreground">Custom hex</span>
                      {customHex && !customHex.match(/^#[0-9a-fA-F]{6}$/) && (
                        <span className="text-xs text-red-500">Invalid format</span>
                      )}
                    </div>
                  </div>

                  {/* Section toggles */}
                  <div className="space-y-3">
                    <Label className="text-sm font-medium">Include Sections</Label>

                    <div className="flex items-center gap-3">
                      <Checkbox
                        id="include-rewrites"
                        checked={includeRewrites}
                        onCheckedChange={(v) => setIncludeRewrites(v === true)}
                        disabled={!hasRewrites}
                      />
                      <label
                        htmlFor="include-rewrites"
                        className={cn(
                          "text-sm cursor-pointer",
                          !hasRewrites && "text-muted-foreground cursor-not-allowed"
                        )}
                      >
                        AI Copy Rewrites
                        {!hasRewrites && (
                          <span className="ml-2 text-xs text-muted-foreground">
                            (no rewrites for this scan)
                          </span>
                        )}
                      </label>
                    </div>

                    <div className="flex items-center gap-3">
                      <Checkbox
                        id="include-history"
                        checked={includeHistory}
                        onCheckedChange={(v) => setIncludeHistory(v === true)}
                        disabled={!hasHistory}
                      />
                      <label
                        htmlFor="include-history"
                        className={cn(
                          "text-sm cursor-pointer",
                          !hasHistory && "text-muted-foreground cursor-not-allowed"
                        )}
                      >
                        Score History
                        {!hasHistory && (
                          <span className="ml-2 text-xs text-muted-foreground">
                            (requires 2+ scans of this URL)
                          </span>
                        )}
                      </label>
                    </div>
                  </div>
                </div>
              ) : (
                // Not Pro+ — show upgrade prompt
                <div className="flex items-start gap-3 rounded-lg border border-amber-200 bg-amber-50 p-4">
                  <Lock className="mt-0.5 h-4 w-4 shrink-0 text-amber-600" />
                  <div>
                    <p className="text-sm font-semibold text-amber-800">Pro plan required</p>
                    <p className="mt-0.5 text-xs text-amber-700">
                      Upgrade to Pro to unlock enhanced branded reports, custom colors,
                      AI copy rewrite sections, and score history pages.
                    </p>
                  </div>
                </div>
              )}
            </>
          )}
        </div>

        <DialogFooter className="gap-2 sm:gap-0">
          <Button
            variant="outline"
            size="sm"
            onClick={() => onOpenChange(false)}
            disabled={isGenerating}
          >
            Cancel
          </Button>
          <Button
            size="sm"
            onClick={handleDownload}
            disabled={isGenerating || (pdfType === "enhanced" && !isProUser)}
            className="min-w-[120px]"
          >
            {isGenerating ? (
              <>
                <RefreshCw className="mr-1.5 h-3.5 w-3.5 animate-spin" />
                Generating…
              </>
            ) : (
              <>
                <Download className="mr-1.5 h-3.5 w-3.5" />
                Download PDF
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

